import { alpha, Avatar, Box, Breadcrumbs, Button, Chip, CircularProgress, Divider, Grid, Stack, Typography, Alert } from '@mui/material';
import useHostDetails from '../../../hooks/host/useHostDetails';
import useCountryDetails from '../../../hooks/country/useCountryDetails';
import { Link, useNavigate, useParams } from 'react-router';
import { ArrowBack, Public } from '@mui/icons-material';
import Surface from '../../components/layout/Surface/Surface';

const HostDetailsPage = () => {
    const navigate = useNavigate();
    const { id } = useParams();
    const { hostDetails, loading, error } = useHostDetails(id);
    const { countryDetails } = useCountryDetails(hostDetails ? String(hostDetails.country_id) : undefined);

    if (loading) {
        return (
            <Surface sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: 300, borderRadius: 3 }}>
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, alignItems: 'center' }}>
                    <CircularProgress />
                    <Typography variant="body2" color="text.secondary">
                        Loading host...
                    </Typography>
                </Box>
            </Surface>
        );
    }

    if (error) {
        return (
            <Box sx={{ py: 2 }}>
                <Alert severity='error' sx={{ borderRadius: 2 }}>{error.message}</Alert>
            </Box>
        );
    }

    if (!hostDetails) {
        return (
            <Box sx={{ py: 2 }}>
                <Alert severity='warning' sx={{ borderRadius: 2 }}>Host not found.</Alert>
            </Box>
        );
    }

    const fullName = `${hostDetails.name} ${hostDetails.surname}`.trim();

    return (
        <Stack spacing={3}>
            {/* Breadcrumbs */}
            <Breadcrumbs>
                <Link to='/hosts' style={{ textDecoration: 'none', color: 'inherit', fontWeight: 500 }}>
                    Hosts
                </Link>
                <Typography color='text.primary'>{fullName}</Typography>
            </Breadcrumbs>

            {/* Main Card */}
            <Surface
                sx={{
                    p: { xs: 3, md: 4 },
                    borderRadius: 4,
                    position: 'relative',
                    overflow: 'hidden',
                    background: (t) =>
                        `linear-gradient(135deg, ${alpha(t.palette.primary.main, 0.08)}, ${alpha(
                            t.palette.secondary.main,
                            0.08
                        )})`,
                }}
            >
                <Grid container spacing={3}>
                    {/* Avatar Section */}
                    <Grid size={{ xs: 12, md: 3 }}>
                        <Box
                            sx={{
                                display: 'flex',
                                justifyContent: 'center',
                            }}
                        >
                            <Avatar
                                sx={{
                                    width: 110,
                                    height: 110,
                                    fontSize: 42,
                                    fontWeight: 700,
                                    bgcolor: 'primary.main',
                                    boxShadow: 3,
                                }}
                            >
                                {hostDetails.name?.[0]}
                                {hostDetails.surname?.[0]}
                            </Avatar>
                        </Box>
                    </Grid>

                    {/* Info Section */}
                    <Grid size={{ xs: 12, md: 9 }}>
                        <Typography
                            variant='h3'
                            sx={{
                                fontWeight: 800,
                                letterSpacing: '-0.03em',
                                mb: 1,
                            }}
                        >
                            {fullName}
                        </Typography>

                        <Typography variant='subtitle1' color='text.secondary' sx={{ mb: 2 }}>
                            Host profile overview
                        </Typography>

                        {/* Country Chip */}
                        <Stack direction='row' spacing={1} sx={{ mb: 3 }}>
                            <Chip
                                component={Link}
                                to={`/countries/${hostDetails.country_id}`}
                                clickable
                                icon={<Public />}
                                label={countryDetails ? countryDetails.name : 'Country'}
                                color='primary'
                                variant='outlined'
                                sx={{
                                    fontWeight: 600,
                                    borderRadius: 2,
                                    '&:hover': {
                                        bgcolor: 'primary.main',
                                        color: 'white',
                                    },
                                }}
                            />
                        </Stack>

                        <Divider sx={{ mb: 3 }} />

                        {/* Actions */}
                        <Stack
                            direction={{ xs: 'column', sm: 'row' }}
                            spacing={2}
                        >
                            <Button
                                variant='outlined'
                                startIcon={<ArrowBack />}
                                onClick={() => navigate('/hosts')}
                                sx={{ borderRadius: 3 }}
                            >
                                All hosts
                            </Button>

                            <Button
                                variant='contained'
                                onClick={() => navigate('/accommodations')}
                                sx={{ borderRadius: 3 }}
                            >
                                Browse stays
                            </Button>
                        </Stack>
                    </Grid>
                </Grid>
            </Surface>
        </Stack>
    );
};

export default HostDetailsPage;

import { Alert, CircularProgress, Typography } from '@mui/material';
import { useMemo } from 'react';
import useHosts from '../../../hooks/host/useHosts';
import useCountries from '../../../hooks/country/useCountries';
import HostGrid from '../../components/host/HostGrid';
import PageHeader from '../../components/layout/PageHeader/PageHeader';
import Section from '../../components/layout/Section/Section';
import Surface from '../../components/layout/Surface/Surface';

const HostsPage = () => {
  const { hosts, loading, error } = useHosts();
  const { countries, loading: countriesLoading, error: countriesError } = useCountries();

  const countryNameById = useMemo(() => {
    const m: Record<number, string> = {};
    for (const c of countries) {
      m[c.id] = c.name;
    }
    return m;
  }, [countries]);

  return (
    <Section>
      <PageHeader
        id='hosts-heading'
        title='Host directory'
        subtitle='Meet the people behind the listings. Open a profile to see where they are based and link through to their country.'
        meta={
          !loading && !error && hosts.length > 0 ? (
            <Typography variant='body2' sx={{ color: 'primary.main', fontWeight: 600 }}>
              {hosts.length} host{hosts.length === 1 ? '' : 's'} in the directory
            </Typography>
          ) : null
        }
      />

      {error && (
        <Alert severity='error' role='alert'>
          {error.message}
        </Alert>
      )}

      {countriesError && (
        <Alert severity='warning' role='status'>
          {countriesError.message} Country names on cards may be incomplete.
        </Alert>
      )}

      {loading && (
        <Surface sx={{ display: 'grid', placeItems: 'center', minHeight: 280 }}>
          <CircularProgress aria-label='Loading hosts' />
        </Surface>
      )}

      {!loading && !error && hosts.length === 0 && (
        <Alert severity='info'>No hosts are listed yet. Check back soon.</Alert>
      )}

      {!loading && !error && hosts.length > 0 && (
        <HostGrid hosts={hosts} countryNameById={countriesLoading ? undefined : countryNameById} />
      )}
    </Section>
  );
};

export default HostsPage;
